CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, name text NOT NULL,
 role text NOT NULL CHECK(role IN ('Owner','Admin','Member','Viewer')), disabled boolean NOT NULL DEFAULT false,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz
);
CREATE TABLE google_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), sub text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, csrf text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, reauthenticated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_owner ON sessions(owner_id);
CREATE TABLE settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO settings(key,value) VALUES ('seat_limit','20'),('maintenance','false');
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid REFERENCES users(id), action text NOT NULL, target_id text, correlation_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_owner_time ON audit_events(owner_id,created_at);
CREATE FUNCTION audit_immutable() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'append-only audit'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER audit_no_changes BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION audit_immutable();
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), data jsonb NOT NULL DEFAULT '{}', secret jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE INDEX invitations_owner ON invitations(owner_id) WHERE revoked_at IS NULL;
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), data jsonb NOT NULL DEFAULT '{}', secret jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE INDEX roles_owner ON roles(owner_id) WHERE revoked_at IS NULL;
