ALTER TABLE nodes ADD COLUMN source_id uuid NOT NULL REFERENCES node_sources(id);
CREATE INDEX nodes_source ON nodes(source_id);
ALTER TABLE subscription_tokens ADD COLUMN token_hash text NOT NULL UNIQUE;
ALTER TABLE background_jobs ADD COLUMN source_id uuid REFERENCES node_sources(id);
ALTER TABLE ai_tasks ADD COLUMN account_id uuid NOT NULL REFERENCES ai_accounts(id);
ALTER TABLE ssh_sessions ADD COLUMN server_id uuid NOT NULL REFERENCES server_connections(id);
ALTER TABLE node_group_grants ADD COLUMN source_id uuid NOT NULL REFERENCES node_sources(id), ADD COLUMN user_id uuid NOT NULL REFERENCES users(id);
ALTER TABLE server_access_grants ADD COLUMN server_id uuid NOT NULL REFERENCES server_connections(id), ADD COLUMN user_id uuid NOT NULL REFERENCES users(id);
CREATE UNIQUE INDEX active_source_grant ON node_group_grants(source_id,user_id) WHERE revoked_at IS NULL;
CREATE UNIQUE INDEX active_server_grant ON server_access_grants(server_id,user_id) WHERE revoked_at IS NULL;
CREATE INDEX job_state ON background_jobs ((data->>'status'), (data->>'nextRun'));
